import os,re,json
from collections import defaultdict as dd
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); di,do=G['Demo pair 1 input'],G['Demo pair 1 output']
H,W=len(di),len(di[0])
def f(g):
    Hh,Ww=len(g),len(g[0])
    hd=[r for r in range(Hh) if len(set(g[r]))==1]
    vd=[c for c in range(Ww) if len(set(g[r][c] for r in range(Hh)))==1]
    hb=[];prev=0
    for d in hd+[Hh]: hb.append((prev,d-1)); prev=d+1
    vb=[];prev=0
    for d in vd+[Ww]: vb.append((prev,d-1)); prev=d+1
    o=[row[:] for row in g]
    by=dd(list)
    for r in range(Hh):
        for c in range(Ww):
            v=g[r][c]
            if v not in (0,8): by[v].append((r,c))
    def bo(r,b): return next(k for k,(a,b_) in enumerate(b) if a<=r<=b_)
    HL=[]; VL=[]
    for v,ps in by.items():
        rr={bo(r,hb) for r,c in ps}; cc={bo(c,vb) for r,c in ps}
        if len(cc)>1: HL.append((next(iter(rr)),min(p[1] for p in ps),max(p[1] for p in ps),v))
        else: VL.append((cc.pop(),min(p[0] for p in ps),max(p[0] for p in ps),v))
    def paint(i,j,v):
        a,b=hb[i]; aa,bb=vb[j]
        for r in range(a,b+1):
            for c in range(aa,bb+1):
                if o[r][c]==0: o[r][c]=v
    for R_,cmin,cmax,v in HL:
        for j in range(len(vb)):
            if not (vb[j][1]<cmin or vb[j][0]>cmax): paint(R_,j,v)
    for Cb,rmin,rmax,v in VL:
        for i in range(len(hb)):
            if not (hb[i][1]<rmin or hb[i][0]>rmax): paint(i,Cb,v)
    hv=set()
    for R_,cmin,cmax,v in HL:
        for j in range(len(vb)):
            if not (vb[j][1]<cmin or vb[j][0]>cmax): hv.add((R_,j))
    vv=set()
    for Cb,rmin,rmax,v in VL:
        for i in range(len(hb)):
            if not (hb[i][1]<rmin or hb[i][0]>rmax): vv.add((i,Cb))
    inter=hv&vv
    for (i,j) in inter:
        for r in range(hb[i][0],hb[i][1]+1):
            for c in range(vb[j][0],vb[j][1]+1):
                o[r][c]=6
    return o
